      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(33, 85, 255, 0.12), transparent 30%),
        radial-gradient(circle at top right, rgba(14, 165, 164, 0.12), transparent 25%),
        var(--bg);
    }

    img {
      display: block;
      max-width: 100%;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      font: inherit;
      cursor: pointer;
    }

    a:focus-visible,
    button:focus-visible,
    input:focus-visible {
      outline: 3px solid rgba(33, 85, 255, 0.28);
      outline-offset: 3px;
    }

    .page-shell {
      width: min(calc(100% - 32px), var(--max-width));
      margin: 0 auto;
    }

    .topbar {
      padding: 24px 0 12px;
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 16px 20px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: var(--surface);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 800;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      width: 38px;
      height: 38px;
      border-radius: 12px;
      display: grid;
      place-items: center;
      color: white;
      background: linear-gradient(135deg, var(--primary), #77a0ff);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3);
    }

    .nav-links,
    .nav-actions {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .nav-links a,
    .nav-actions a {
      padding: 10px 14px;
      color: var(--muted);
      border-radius: 999px;
      transition: background-color 0.2s ease, color 0.2s ease;
    }

    .nav-links a:hover,
    .nav-actions a:hover,
    .chip:hover,
    .ghost-button:hover {
      background: rgba(20, 32, 51, 0.06);
      color: var(--text);
    }

    .primary-button,
    .ghost-button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 13px 18px;
      border-radius: 999px;
      border: 0;
      font-weight: 700;
      transition: transform 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease;
    }

    .primary-button {
      color: white;
      background: linear-gradient(135deg, var(--primary), #5f86ff);
      box-shadow: 0 16px 28px rgba(33, 85, 255, 0.26);
    }

    .primary-button:hover {
      transform: translateY(-1px);
      background: linear-gradient(135deg, var(--primary-dark), var(--primary));
    }

    .ghost-button {
      color: var(--text);
      background: rgba(255, 255, 255, 0.66);
      border: 1px solid var(--line);
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.9fr);
      gap: 24px;
      padding: 24px 0 20px;
    }

    .hero-copy,
    .hero-panel,
    .section-card,
    .deal-card,
    .editorial-card,
    .newsletter {
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      background: var(--surface);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: 36px;
      min-height: 540px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      background:
        linear-gradient(145deg, rgba(255, 255, 255, 0.94), rgba(255, 255, 255, 0.72)),
        radial-gradient(circle at top right, rgba(33, 85, 255, 0.16), transparent 32%);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(33, 85, 255, 0.08);
      color: var(--primary);
      font-size: 0.92rem;
      font-weight: 700;
      width: fit-content;
    }

    h1,
    h2,
    h3,
    p {
      margin: 0;
    }

    .hero-copy h1 {
      margin-top: 18px;
      font-size: clamp(2.8rem, 4vw, 5.2rem);
      line-height: 0.97;
      letter-spacing: -0.04em;
      max-width: 10ch;
    }

    .hero-copy p {
      margin-top: 18px;
      max-width: 56ch;
      font-size: 1.05rem;
      line-height: 1.65;
      color: var(--muted);
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 28px;
    }

    .hero-metrics {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
      margin-top: 34px;
    }

    .metric {
      padding: 18px;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.74);
      border: 1px solid rgba(20, 32, 51, 0.06);
    }

    .metric strong {
      display: block;
      font-size: 1.3rem;
      margin-bottom: 6px;
    }

    .metric span {
      color: var(--muted);
      font-size: 0.94rem;
    }

    .hero-panel {
      padding: 26px;
      display: grid;
      grid-template-rows: auto 1fr auto;
      gap: 18px;
      overflow: hidden;
      position: relative;
      background:
        linear-gradient(160deg, rgba(20, 32, 51, 0.96), rgba(28, 51, 107, 0.9)),
        radial-gradient(circle at top left, rgba(119, 160, 255, 0.35), transparent 32%);
      color: white;
    }

    .hero-panel::after {
      content: "";
      position: absolute;
      inset: auto -10% -20% auto;
      width: 320px;
      height: 320px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255, 122, 89, 0.38), transparent 65%);
      pointer-events: none;
    }

    .hero-product {
      position: relative;
      z-index: 1;
      padding: 28px;
      border-radius: var(--radius-lg);
      min-height: 320px;
      background:
        linear-gradient(145deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.04)),
        radial-gradient(circle at top, rgba(255, 255, 255, 0.14), transparent 42%);
      border: 1px solid rgba(255, 255, 255, 0.14);
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .product-visual {
      width: min(100%, 300px);
      aspect-ratio: 1 / 1;
      margin: 0 auto;
      border-radius: 32px;
      background:
        radial-gradient(circle at 50% 40%, rgba(255, 255, 255, 0.95), rgba(197, 211, 255, 0.9) 45%, rgba(72, 100, 169, 0.85) 100%);
      box-shadow:
        inset 0 1px 24px rgba(255, 255, 255, 0.55),
        0 26px 40px rgba(11, 19, 43, 0.28);
      position: relative;
      overflow: hidden;
    }

    .product-visual::before,
    .product-visual::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.9);
    }

    .product-visual::before {
      width: 54%;
      height: 26%;
      left: 23%;
      top: 18%;
      box-shadow: 0 16px 40px rgba(28, 51, 107, 0.15);
    }

    .product-visual::after {
      width: 70%;
      height: 46%;
      left: 15%;
      bottom: 16%;
      border-radius: 36px;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(219, 227, 255, 0.95));
      box-shadow: 0 18px 34px rgba(28, 51, 107, 0.24);
    }

    .panel-tag {
      display: inline-flex;
      width: fit-content;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.12);
      color: rgba(255, 255, 255, 0.82);
      font-size: 0.88rem;
      font-weight: 700;
    }

    .panel-footer {
      display: flex;
      justify-content: space-between;
      gap: 16px;
      align-items: end;
      position: relative;
      z-index: 1;
    }

    .panel-footer p {
      color: rgba(255, 255, 255, 0.74);
      font-size: 0.96rem;
      line-height: 1.55;
      max-width: 28ch;
    }

    .panel-price {
      text-align: right;
    }

    .panel-price strong {
      display: block;
      font-size: 1.8rem;
      line-height: 1;
    }

    main {
      padding-bottom: 48px;
    }

    section {
      padding: 20px 0;
    }

    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 18px;
    }

    .section-head p {
      color: var(--muted);
      line-height: 1.6;
      max-width: 56ch;
      margin-top: 10px;
    }

    .section-card {
      padding: 28px;
    }

    .toolbar {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-bottom: 20px;
    }

    .chip {
      border: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.9);
      color: var(--muted);
      padding: 10px 14px;
      border-radius: 999px;
      font-weight: 700;
      transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
    }

    .chip[aria-pressed="true"] {
      background: rgba(33, 85, 255, 0.12);
      color: var(--primary);
      border-color: rgba(33, 85, 255, 0.18);
    }

    .product-grid,
    .deal-grid,
    .editorial-grid {
      display: grid;
      gap: 18px;
    }

    .product-grid {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .product-card {
      padding: 18px;
      border-radius: var(--radius-md);
      background: var(--surface-strong);
      border: 1px solid rgba(20, 32, 51, 0.07);
      display: flex;
      flex-direction: column;
      gap: 14px;
      min-height: 100%;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    .product-card:hover,
    .deal-card:hover,
    .editorial-card:hover {
      transform: translateY(-3px);
      box-shadow: 0 24px 40px rgba(25, 39, 73, 0.12);
    }

    .product-media {
      height: 210px;
      border-radius: var(--radius-md);
      position: relative;
      overflow: hidden;
      background:
        linear-gradient(135deg, rgba(33, 85, 255, 0.18), rgba(14, 165, 164, 0.18)),
        #eef3ff;
    }

    .product-media::before,
    .product-media::after {
      content: "";
      position: absolute;
      inset: auto;
      border-radius: 24px;
      background: rgba(255, 255, 255, 0.92);
    }

    .product-media::before {
      width: 58%;
      height: 58%;
      left: 21%;
      top: 18%;
      box-shadow: 0 18px 28px rgba(33, 85, 255, 0.12);
    }

    .product-media::after {
      width: 40%;
      height: 18%;
      left: 30%;
      bottom: 18%;
    }

    .product-card:nth-child(2) .product-media {
      background: linear-gradient(135deg, rgba(255, 122, 89, 0.16), rgba(255, 204, 102, 0.16)), #fff5ef;
    }

    .product-card:nth-child(3) .product-media {
      background: linear-gradient(135deg, rgba(14, 165, 164, 0.18), rgba(145, 224, 212, 0.26)), #ecfbf8;
    }

    .product-card:nth-child(4) .product-media {
      background: linear-gradient(135deg, rgba(105, 99, 255, 0.16), rgba(204, 198, 255, 0.22)), #f2efff;
    }

    .product-topline,
    .product-meta,
    .deal-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }

    .badge {
      display: inline-flex;
      align-items: center;
      padding: 7px 10px;
      border-radius: 999px;
      background: rgba(20, 32, 51, 0.06);
      color: var(--muted);
      font-size: 0.82rem;
      font-weight: 700;
    }

    .rating {
      color: #f59e0b;
      font-size: 0.94rem;
      font-weight: 700;
    }

    .product-card h3,
    .deal-card h3,
    .editorial-card h3 {
      font-size: 1.12rem;
      line-height: 1.3;
    }

    .product-card p,
    .deal-card p,
    .editorial-card p {
      color: var(--muted);
      line-height: 1.6;
      font-size: 0.96rem;
    }

    .price {
      font-size: 1.24rem;
      font-weight: 800;
      letter-spacing: -0.02em;
    }

    .price small {
      color: var(--muted);
      font-weight: 600;
      text-decoration: line-through;
      margin-left: 8px;
      font-size: 0.95rem;
    }

    .deal-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .deal-card {
      padding: 24px;
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(255, 255, 255, 0.84));
    }

    .deal-card.featured {
      background:
        linear-gradient(160deg, rgba(33, 85, 255, 0.96), rgba(42, 124, 255, 0.9)),
        radial-gradient(circle at top right, rgba(255, 255, 255, 0.2), transparent 32%);
      color: white;
    }

    .deal-card.featured p,
    .deal-card.featured .deal-meta,
    .deal-card.featured .timer-label {
      color: rgba(255, 255, 255, 0.8);
    }

    .deal-highlight {
      margin: 18px 0;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1;
      font-weight: 900;
      letter-spacing: -0.04em;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 10px;
      margin-top: 20px;
    }

    .countdown-item {
      padding: 14px 10px;
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.12);
      text-align: center;
    }

    .countdown-item strong {
      display: block;
      font-size: 1.2rem;
      margin-bottom: 4px;
    }

    .timer-label {
      font-size: 0.78rem;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .editorial-grid {
      grid-template-columns: 1.25fr 0.95fr 0.95fr;
    }

    .editorial-card {
      overflow: hidden;
      min-height: 100%;
      background: rgba(255, 255, 255, 0.88);
    }

    .editorial-visual {
      min-height: 210px;
      background:
        linear-gradient(135deg, rgba(20, 32, 51, 0.84), rgba(33, 85, 255, 0.52)),
        radial-gradient(circle at top left, rgba(255, 255, 255, 0.18), transparent 30%);
    }

    .editorial-card:nth-child(2) .editorial-visual {
      background: linear-gradient(135deg, rgba(14, 165, 164, 0.82), rgba(145, 224, 212, 0.48));
    }

    .editorial-card:nth-child(3) .editorial-visual {
      background: linear-gradient(135deg, rgba(255, 122, 89, 0.84), rgba(255, 196, 123, 0.56));
    }

    .editorial-body {
      padding: 22px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .newsletter {
      margin-top: 20px;
      padding: 28px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .newsletter p {
      color: var(--muted);
      line-height: 1.6;
      margin-top: 8px;
    }

    .newsletter-form {
      display: flex;
      gap: 10px;
      width: min(100%, 420px);
    }

    .newsletter-form input {
      flex: 1;
      min-width: 0;
      padding: 14px 16px;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: #fff;
      font: inherit;
      color: var(--text);
    }

    .newsletter-status {
      min-height: 1.5em;
      margin-top: 10px;
      color: var(--primary);
      font-weight: 700;
    }

    .footer {
      padding: 0 0 36px;
      color: var(--muted);
    }

    .footer-card {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      padding: 18px 4px 0;
      font-size: 0.94rem;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    [data-category][hidden] {
      display: none;
    }

    @media (max-width: 1080px) {
      .hero,
      .product-grid,
      .deal-grid,
      .editorial-grid,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .newsletter {
        display: grid;
      }
    }

    @media (max-width: 880px) {
      .nav {
        border-radius: 28px;
        flex-wrap: wrap;
      }

      .nav-links {
        order: 3;
        width: 100%;
        justify-content: center;
        flex-wrap: wrap;
      }

      .hero-copy {
        min-height: auto;
      }

      .hero-metrics {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 640px) {
      .page-shell {
        width: min(calc(100% - 20px), var(--max-width));
      }

      .topbar {
        padding-top: 14px;
      }

      .hero-copy,
      .hero-panel,
      .section-card,
      .deal-card,
      .newsletter {
        padding: 22px;
      }

      .hero-copy h1 {
        max-width: none;
      }

      .panel-footer,
      .footer-card,
      .newsletter-form {
        flex-direction: column;
        align-items: stretch;
      }

      .countdown {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="page-shell">
      <nav class="nav" aria-label="Primary">
        <a class="brand" href="#top">
          <span class="brand-mark" aria-hidden="true">N</span>
          <span>Northstar Goods</span>
        </a>
        <div class="nav-links">
          <a href="#featured">Featured</a>
          <a href="#deals">Deals</a>
          <a href="#editorial">Editorial</a>
          <a href="#membership">Membership</a>
        </div>
        <div class="nav-actions">
          <a href="#featured" aria-label="Search products">Search</a>
          <a href="#deals" aria-label="View cart">Cart (2)</a>
          <a class="primary-button" href="#featured">Shop now</a>
        </div>
      </nav>
    </div>
  </header>

  <main id="top">
    <div class="page-shell">
      <section class="hero" aria-labelledby="hero-title">
        <div class="hero-copy">
          <div>
            <span class="eyebrow">Spring collection 2026</span>
            <h1 id="hero-title">Designed for everyday retail moments.</h1>
            <p>
              Discover premium essentials, limited-run deals, and fresh editorial picks curated to make
              your home, commute, and workspace feel more considered.
            </p>
            <div class="hero-actions">
              <a class="primary-button" href="#featured">Browse featured</a>
              <a class="ghost-button" href="#editorial">Read the journal</a>
            </div>
          </div>

          <div class="hero-metrics" aria-label="Store highlights">
            <div class="metric">
              <strong>120+</strong>
              <span>new arrivals this week</span>
            </div>
            <div class="metric">
              <strong>4.8/5</strong>
              <span>average customer rating</span>
            </div>
            <div class="metric">
              <strong>Free</strong>
              <span>shipping over $75</span>
            </div>
          </div>
        </div>

        <aside class="hero-panel" aria-label="Featured collection card">
          <span class="panel-tag">Product spotlight</span>
          <div class="hero-product">
            <div class="product-visual" aria-hidden="true"></div>
            <div>
              <h2>Halo Smart Lamp</h2>
              <p>Ambient lighting with adaptive tones, wireless charging, and a sculpted matte finish.</p>
            </div>
          </div>
          <div class="panel-footer">
            <p>Minimal profile. Warm illumination. Built to elevate desks, shelves, and bedside routines.</p>
            <div class="panel-price">
              <span>From</span>
              <strong>$129</strong>
            </div>
          </div>
        </aside>
      </section>

      <section id="featured" aria-labelledby="featured-title">
        <div class="section-head">
          <div>
            <span class="eyebrow">Featured products</span>
            <h2 id="featured-title">Best sellers with a calm, premium feel.</h2>
            <p>Filter the assortment to explore standout picks across home, tech, and travel.</p>
          </div>
        </div>

        <div class="section-card">
          <div class="toolbar" role="toolbar" aria-label="Filter featured products">
            <button class="chip" type="button" aria-pressed="true" data-filter="all">All</button>
            <button class="chip" type="button" aria-pressed="false" data-filter="home">Home</button>
            <button class="chip" type="button" aria-pressed="false" data-filter="tech">Tech</button>
            <button class="chip" type="button" aria-pressed="false" data-filter="travel">Travel</button>
          </div>

          <div class="product-grid">
            <article class="product-card" data-category="home">
              <div class="product-media" aria-hidden="true"></div>
              <div class="product-topline">
                <span class="badge">Home</span>
                <span class="rating">★★★★★</span>
              </div>
              <div>
                <h3>Arc Ceramic Diffuser</h3>
                <p>Soft fragrance diffusion with a low-profile silhouette for living rooms and bedrooms.</p>
              </div>
              <div class="product-meta">
                <div class="price">$84</div>
                <a class="ghost-button" href="#cart">Add to cart</a>
              </div>
            </article>

            <article class="product-card" data-category="tech">
              <div class="product-media" aria-hidden="true"></div>
              <div class="product-topline">
                <span class="badge">Tech</span>
                <span class="rating">★★★★★</span>
              </div>
              <div>
                <h3>Pulse ANC Headphones</h3>
                <p>Immersive audio, 32-hour battery life, and breathable ear cushions in a compact fold.</p>
              </div>
              <div class="product-meta">
                <div class="price">$219 <small>$279</small></div>
                <a class="ghost-button" href="#cart">Add to cart</a>
              </div>
            </article>

            <article class="product-card" data-category="travel">
              <div class="product-media" aria-hidden="true"></div>
              <div class="product-topline">
                <span class="badge">Travel</span>
                <span class="rating">★★★★☆</span>
              </div>
              <div>
                <h3>Transit Weekender</h3>
                <p>Structured carryall with modular packing cubes, hidden pockets, and weather-safe fabric.</p>
              </div>
              <div class="product-meta">
                <div class="price">$148</div>
