  <script>
    const filterButtons = document.querySelectorAll("[data-filter]");
    const productCards = document.querySelectorAll("[data-category]");

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        const nextFilter = button.dataset.filter;

        filterButtons.forEach((chip) => {
          chip.setAttribute("aria-pressed", String(chip === button));
        });

        productCards.forEach((card) => {
          const matches = nextFilter === "all" || card.dataset.category === nextFilter;
          card.hidden = !matches;
        });
      });
    });

    const targetDate = new Date(Date.now() + ((2 * 24 + 12) * 60 * 60 + 45 * 60 + 8) * 1000);
    const timerParts = {
      days: document.getElementById("days"),
      hours: document.getElementById("hours"),
      minutes: document.getElementById("minutes"),
      seconds: document.getElementById("seconds")
    };

    function updateCountdown() {
      const remaining = Math.max(targetDate.getTime() - Date.now(), 0);
      const days = Math.floor(remaining / (1000 * 60 * 60 * 24));
      const hours = Math.floor((remaining / (1000 * 60 * 60)) % 24);
      const minutes = Math.floor((remaining / (1000 * 60)) % 60);
      const seconds = Math.floor((remaining / 1000) % 60);

      timerParts.days.textContent = String(days).padStart(2, "0");
      timerParts.hours.textContent = String(hours).padStart(2, "0");
      timerParts.minutes.textContent = String(minutes).padStart(2, "0");
      timerParts.seconds.textContent = String(seconds).padStart(2, "0");
    }

    const newsletterForm = document.querySelector(".newsletter-form");
    const newsletterEmail = document.getElementById("email");
    const newsletterStatus = document.getElementById("newsletter-status");

    newsletterForm.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!newsletterEmail.value.trim()) {
        newsletterStatus.textContent = "Enter an email address to join.";
        newsletterEmail.focus();
        return;
      }

      newsletterStatus.textContent = "Thanks for joining Northstar updates.";
      newsletterForm.reset();
    });

    updateCountdown();
    window.setInterval(updateCountdown, 1000);
  </script>
